import{z as l,x as p,o as s,c as d,q as i,j as t,D as a,d as n,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Mortensen–Pissarides 搜寻","description":"","frontmatter":{"title":"Mortensen–Pissarides 搜寻","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mp-1994-paper.md","filePath":"econ/mp-1994-paper.md","lastUpdated":1791063341000}'),A={name:"econ/mp-1994-paper.md"};function m(D,e,c,h,u,P){const r=p("Mermaid");return s(),d("div",null,[e[2]||(e[2]=i('<h1 id="mortensen–pissarides-搜寻" tabindex="-1">Mortensen–Pissarides 搜寻 <a class="header-anchor" href="#mortensen–pissarides-搜寻" aria-label="Permalink to &quot;Mortensen–Pissarides 搜寻&quot;">​</a></h1><div class="epigraph"><p>失业与空岗可以并存：匹配需要时间，工资在配对之后分剩余；创造与破坏是两条流，不是一条劳动需求曲线上的点。</p><footer>—— Mortensen and Pissarides, Job Creation and Job Destruction in the Theory of Unemployment, Review of Economic Studies, 1994</footer></div><p>附录对照，不插入主干。<a href="/econ/mundell-1963-paper">上一课</a>对照的是开放经济里稳定化工具随汇率制度换位。本篇对照 <strong>Mortensen–Pissarides 1994 原文的问题设定</strong>：把失业写成搜寻摩擦下的流量均衡，而不是劳动市场出清失败的同义反复。主干<a href="/econ/search-matching-dmp">DMP 搜寻匹配</a>已取匹配函数与 Beveridge；这里对照 <em>RES</em> 如何把岗位创造与岗位破坏写进同一篇，以及它为何不是 1963 年资本流动的续篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>瓦尔拉斯劳动市场里，工资出清，失业只剩摩擦或自愿。宏观要同时看到失业与空岗、以及岗位的生灭。Pissarides 的匹配函数把双方的寻找收成见面概率；Mortensen 的搜寻与工资议价把剩余切开。1994 年原文的缺口是：在已有匹配框架里加入<strong>内生破坏</strong>——生产率 idiosyncratic 冲击使现有岗位的剩余价值变负，岗位被毁，工人回到失业，同时企业按自由进入创造新岗。失业是创造流与破坏流的差，不是静态剩余。</p><p><span class="marginnote">常见误区：以为空岗与失业并存是数据矛盾。搜寻模型里二者同时为正才正常——企业在等人，人在等见面，两边都在付等待成本。这不是「市场没出清」，而是摩擦经济的定义现象。</span></p><p>会议式的宏观计量把失业当菲利普斯的另一轴。Lucas 原文已经警告简化式。MP 给的是另一套结构：摩擦参数与议价权，而不是一条可平移的劳动需求。</p><p><span class="marginnote">Mortensen and Pissarides, <em>Review of Economic Studies</em> 61(3), 1994, 397–415。不要发明 arXiv。DMP 是 Diamond–Mortensen–Pissarides 传统的统称；本篇对照的是 1994 年创造–破坏这一刀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>匹配函数 \\(m(u,v)\\)，失业 \\(u\\)、空岗 \\(v\\)，紧度 \\(\\theta=v/u\\)。空岗的见面率与失业的见面率由 \\(m\\) 的一阶齐次给出。岗位有 idiosyncratic 生产率，跌破内生阈值则破坏。工资由纳什议价分匹配剩余。自由进入：空岗的期望价值等于招工成本。稳态：\\(u\\) 使流出（匹配）等于流入（破坏加外生分离，视设定）。</p><p><span class="marginnote">「紧度」\\(\\theta=v/u\\) 翻译成大白话：平均每个失业者对应几个空岗。\\(\\theta=1\\) 是岗位与人一样多；\\(\\theta\\) 越大市场越「抢人」，失业者见面越快、工资议价越硬，企业则越难招人。</span></p><p><span class="marginnote">数字实例：失业像浴缸水位——流入是每月被毁的岗位，流出是每月成功匹配的人数。若月度破坏率为 2%、失业者月度找到工作的概率为 30%，稳态失业率约 \\(2/(2+30)\\approx 6.3\\%\\)。破坏率上升或匹配变慢，水位都会抬高。</span></p>',12)),(s(),t(B,null,{default:a(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%8C%B9%E9%85%8D%E5%87%BD%E6%95%B0%22%5D%20--%3E%20MEET%5B%22%E8%A7%81%E9%9D%A2%E6%A6%82%E7%8E%87%22%5D%0A%20%20ID%5B%22%E5%B2%97%E4%BD%8D%E7%89%B9%E6%9C%89%E5%86%B2%E5%87%BB%22%5D%20--%3E%20DEST%5B%22%E5%86%85%E7%94%9F%E7%A0%B4%E5%9D%8F%22%5D%0A%20%20FREE%5B%22%E8%87%AA%E7%94%B1%E8%BF%9B%E5%85%A5%22%5D%20--%3E%20CRE%5B%22%E5%B2%97%E4%BD%8D%E5%88%9B%E9%80%A0%22%5D%0A%20%20MEET%20--%3E%20U%5B%22%E7%A8%B3%E6%80%81%E5%A4%B1%E4%B8%9A%22%5D%0A%20%20DEST%20--%3E%20U%0A%20%20CRE%20--%3E%20U%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("p",null,"主干课已写 Beveridge 曲线；附录不重画，只对照 1994 年把破坏从外生分离升级为阈值决策，使周期里破坏可以升、创造可以降。",-1)),e[4]||(e[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=E("p",null,"机制是配对的时间与剩余分享。企业付招工成本，换一个随机生产率的岗位；工人付失业时间，换一个随机工资。工资不能事先把所有状态写完，议价在见面后发生，于是空岗与失业可以同时为正——两边都在等更好的见面，而不是拒绝「市场工资」。破坏是当继续匹配的剩余低于拆开的期权。Hosios 条件（议价份额对齐匹配弹性）才有效率；否则创造过度或不足。原文把效率当参照，不把任意议价权当最优。",-1)),(s(),t(B,null,{default:a(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20FREE%5B%22%E8%87%AA%E7%94%B1%E8%BF%9B%E5%85%A5%EF%BC%9A%E7%A9%BA%E5%B2%97%E6%9C%9F%E6%9C%9B%E4%BB%B7%E5%80%BC%20%3D%20%E6%8B%9B%E5%B7%A5%E6%88%90%E6%9C%AC%22%5D%20--%3E%20VAC%5B%22%E7%A9%BA%E5%B2%97%E7%AD%89%E5%BE%85%E8%A7%81%E9%9D%A2%22%5D%0A%20%20USEEK%5B%22%E5%A4%B1%E4%B8%9A%E8%80%85%E4%BB%98%E6%97%B6%E9%97%B4%E5%AF%BB%E6%89%BE%22%5D%20--%3E%20MEET%5B%22%E5%8C%B9%E9%85%8D%E7%9B%B8%E9%81%87%22%5D%0A%20%20VAC%20--%3E%20MEET%0A%20%20MEET%20--%3E%20JOB%5B%22%E5%9C%A8%E5%B2%97%EF%BC%9A%E7%BA%B3%E4%BB%80%E8%AE%AE%E4%BB%B7%E5%88%86%E5%89%A9%E4%BD%99%22%5D%0A%20%20SHOCK%5B%22%E5%B2%97%E4%BD%8D%E7%89%B9%E6%9C%89%E7%94%9F%E4%BA%A7%E7%8E%87%E5%86%B2%E5%87%BB%22%5D%20--%3E%20TH%7B%22%E5%89%A9%E4%BD%99%E6%98%AF%E5%90%A6%E8%B7%8C%E7%A0%B4%E9%98%88%E5%80%BC%EF%BC%9F%22%7D%0A%20%20JOB%20--%3E%20TH%0A%20%20TH%20--%20%22%E5%90%A6%EF%BC%8C%E7%BB%A7%E7%BB%AD%22%20--%3E%20JOB%0A%20%20TH%20--%20%22%E6%98%AF%22%20--%3E%20DEST%5B%22%E5%B2%97%E4%BD%8D%E7%A0%B4%E5%9D%8F%EF%BC%8C%E5%B7%A5%E4%BA%BA%E5%9B%9E%E7%82%89%22%5D%0A%20%20DEST%20--%3E%20USEEK%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p>与 Mundell 1963 的对照只在附录链上：都是宏观结构，一个是开放宏观的制度分叉，一个是劳动流量。不要把搜寻插进不可能三角主干。</p><h3 id="对照主干-dmp-课-不插入开放宏观之间" tabindex="-1">对照主干 DMP 课，不插入开放宏观之间 <a class="header-anchor" href="#对照主干-dmp-课-不插入开放宏观之间" aria-label="Permalink to &quot;对照主干 DMP 课，不插入开放宏观之间&quot;">​</a></h3><p>主干<a href="/econ/search-matching-dmp">DMP 搜寻匹配</a>已取匹配函数、紧度与失业的流量定义。本附录对照 <em>RES</em> 1994：idiosyncratic 冲击、内生破坏、创造与破坏的共同决定。把这篇接在 Mundell 原文之后只因为宏观附录链如此排，<strong>不插入</strong>开放课序，也不把岗位匹配写成限价簿撮合。</p><p><span class="marginnote">Shimer 后来指出：标准校准下失业波动太小。那是定量刺，不是 1994 年定理作废。附录不审波动表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1994 写成已经包含内生搜寻强度的全部变体，或已经解决工资刚性。效率工资、交错合同是并列摩擦。也不要把匹配函数写成生产函数的劳动项去替代索洛残差课。</p><p>读完回主干搜寻课。宏观附录链下一篇转到股权溢价原文。</p><p>自由进入把空岗价值钉在招工成本上。没有这条，创造流没有锚。</p><p>工资若完全灵活且议价份额碰巧满足 Hosios，搜寻仍留下摩擦失业，只是创造量有效。工资粘性、效率工资是再加一层，不是 1994 年已经写进破坏阈值的东西。</p><p>读完回主干<a href="/econ/search-matching-dmp">DMP 搜寻匹配</a>。不要把这篇接在 Mundell 之后当作开放宏观的下一课。股权溢价原文是附录链上的下一篇，不是劳动市场的推论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Mortensen–Pissarides 1994：失业是匹配摩擦下创造流与破坏流的稳态。</li><li>内生破坏由岗位特有生产率的阈值给出；工资在配对后议价。</li><li>空岗与失业并存是搜寻的定义现象，不是劳动需求没画对。</li><li>Hosios 条件才有效率；任意议价权不是最优。</li><li>读完回主干 DMP 课；不插入开放宏观主干。</li><li>出处：Mortensen and Pissarides, <em>RES</em> 1994。</li></ul>',12))])}const M=l(A,[["render",m]]);export{f as __pageData,M as default};
